<?php
$pid=project_id();
$tabs=['overall'=>'Overall','materials'=>'Materials','categories'=>'Categories','work'=>'Work types','dates'=>'Date-wise','labour'=>'Labour / Theka','suppliers'=>'Suppliers','payments'=>'Payments','rates'=>'Rate history'];
$tab=isset($tabs[$_GET['tab']??''])?$_GET['tab']:'overall';
$preset=$_GET['period']??'all'; $from=''; $to='';
switch($preset){
case 'today': $from=$to=date('Y-m-d'); break;
case 'week': $from=date('Y-m-d',strtotime('monday this week'));$to=date('Y-m-d',strtotime('sunday this week'));break;
case 'month':$from=date('Y-m-01');$to=date('Y-m-t');break;
case 'last':$from=date('Y-m-01',strtotime('first day of last month'));$to=date('Y-m-t',strtotime('last day of last month'));break;
case 'custom':$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??'');break;
default:$preset='all';
}
$filterError='';
try { if($from!=='')valid_date($from); if($to!=='')valid_date($to); if($from!==''&&$to!==''&&$from>$to)throw new InvalidArgumentException('Enter a valid date range.'); } catch(InvalidArgumentException $exception) { $filterError='Enter a valid date range.'; $from=$to=''; }
$workId=max(0,(int)($_GET['work']??0));$categoryId=max(0,(int)($_GET['category']??0));$itemId=max(0,(int)($_GET['item']??0));$contactId=max(0,(int)($_GET['contact']??0));
$paymentStatus=in_array($_GET['payment_status']??'', ['paid','partial','unpaid'],true)?$_GET['payment_status']:'';
$lineFilters=in_array($tab,['overall','materials','categories','work','dates','rates'],true);
if(!$lineFilters){$categoryId=$itemId=0;$paymentStatus='';}
if(in_array($tab,['suppliers','payments'],true))$workId=0;
function report_dates(string $column,array &$params,string $from,string $to):string{
 $sql='';if($from!==''){$sql.=" AND $column>=?";$params[]=$from;}if($to!==''){$sql.=" AND $column<=?";$params[]=$to;}return $sql;
}
function report_sum(array $rows,string $key):string{$sum='0';foreach($rows as $r)$sum=bcadd($sum,(string)$r[$key],8);return $sum;}
function report_group(array &$groups,string $key,string $name,string $amount):void{if(!isset($groups[$key]))$groups[$key]=['name'=>$name,'amount'=>'0','links'=>[]];$groups[$key]['amount']=bcadd($groups[$key]['amount'],$amount,2);}
$allocationSql="SELECT a.expense_id,SUM(a.amount) paid FROM payment_allocations a JOIN payments p ON p.id=a.payment_id AND p.status='active' GROUP BY a.expense_id";
$params=[$pid];$where="e.project_id=? AND e.status='active'".report_dates('e.expense_date',$params,$from,$to);
foreach(['l.work_type_id'=>$workId,'l.category_id'=>$categoryId,'l.item_id'=>$itemId,'e.contact_id'=>$contactId] as $column=>$value)if($value){$where.=" AND $column=?";$params[]=$value;}
if($paymentStatus==='paid')$where.=' AND COALESCE(a.paid,0)>=e.total';
if($paymentStatus==='partial')$where.=' AND COALESCE(a.paid,0)>0 AND COALESCE(a.paid,0)<e.total';
if($paymentStatus==='unpaid')$where.=' AND COALESCE(a.paid,0)=0';
$lines=rows("SELECT l.*,e.expense_date,e.contact_id,e.total expense_total,COALESCE(a.paid,0) expense_paid,i.name item_name,c.name category_name,c.kind,t.name work_name,n.name contact_name FROM expense_items l JOIN expenses e ON e.id=l.expense_id JOIN items i ON i.id=l.item_id JOIN categories c ON c.id=l.category_id JOIN work_types t ON t.id=l.work_type_id LEFT JOIN contacts n ON n.id=e.contact_id LEFT JOIN ($allocationSql) a ON a.expense_id=e.id WHERE $where ORDER BY e.expense_date DESC,e.id DESC,l.id",$params);
$params=[$pid];$where="c.project_id=?";
if($contactId){$where.=' AND c.contact_id=?';$params[]=$contactId;}if($workId){$where.=' AND c.work_type_id=?';$params[]=$workId;}
$contracts=rows("SELECT c.*,n.name contact_name,t.name work_name,COALESCE(w.recognized,0) recognized,COALESCE(a.paid,0) paid FROM contracts c JOIN contacts n ON n.id=c.contact_id JOIN work_types t ON t.id=c.work_type_id LEFT JOIN (SELECT contract_id,SUM(amount) recognized FROM contract_work_costs WHERE status='active' GROUP BY contract_id) w ON w.contract_id=c.id LEFT JOIN (SELECT a.contract_id,SUM(a.amount) paid FROM payment_allocations a JOIN payments p ON p.id=a.payment_id AND p.status='active' GROUP BY a.contract_id) a ON a.contract_id=c.id WHERE $where ORDER BY c.contract_date DESC,c.id DESC",$params);
$params=[$pid];$where="c.project_id=? AND w.status='active'".report_dates('w.cost_date',$params,$from,$to);
if($workId){$where.=' AND c.work_type_id=?';$params[]=$workId;}if($contactId){$where.=' AND c.contact_id=?';$params[]=$contactId;}
$costs=($categoryId||$itemId||$paymentStatus)?[]:rows("SELECT w.*,c.title,c.work_type_id,c.contact_id,t.name work_name,n.name contact_name FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id JOIN work_types t ON t.id=c.work_type_id JOIN contacts n ON n.id=c.contact_id WHERE $where ORDER BY w.cost_date DESC,w.id DESC",$params);
$params=[$pid];$where="p.project_id=? AND p.status='active'".report_dates('p.payment_date',$params,$from,$to);
if($contactId){$where.=' AND p.contact_id=?';$params[]=$contactId;}
$payments=rows("SELECT p.*,n.name contact_name,COALESCE(a.allocated,0) allocated FROM payments p LEFT JOIN contacts n ON n.id=p.contact_id LEFT JOIN (SELECT payment_id,SUM(amount) allocated FROM payment_allocations GROUP BY payment_id) a ON a.payment_id=p.id WHERE $where ORDER BY p.payment_date DESC,p.id DESC",$params);
$paymentLinks=rows("SELECT a.*,p.payment_date,p.method,e.expense_date,c.title FROM payment_allocations a JOIN payments p ON p.id=a.payment_id LEFT JOIN expenses e ON e.id=a.expense_id LEFT JOIN contracts c ON c.id=a.contract_id WHERE p.project_id=? AND p.status='active'",[$pid]);$linksByPayment=[];foreach($paymentLinks as $a)$linksByPayment[$a['payment_id']][]=$a;
$expenseCohort=[];foreach($lines as $l)$expenseCohort[$l['expense_id']]=['total'=>$l['expense_total'],'paid'=>$l['expense_paid']];
$unallocated='0';foreach($payments as $p)$unallocated=bcadd($unallocated,bcsub($p['amount'],$p['allocated'],2),2);
$purchaseTotal=report_sum($lines,'total');$workTotal=report_sum($costs,'amount');
$contractPeriod=[];foreach($costs as $w)$contractPeriod[$w['contract_id']]=bcadd($contractPeriod[$w['contract_id']]??'0',$w['amount'],2);
$contractBefore=[];
if($from!=='')foreach(rows("SELECT w.contract_id,SUM(w.amount) amount FROM contract_work_costs w JOIN contracts c ON c.id=w.contract_id WHERE c.project_id=? AND w.status='active' AND w.cost_date<? GROUP BY w.contract_id",[$pid,$from]) as $r)$contractBefore[$r['contract_id']]=$r['amount'];
function report_contract_due(string $periodCost,string $paid,string $earlierCost):string {
 $available=bccomp($paid,$earlierCost,2)>0?bcsub($paid,$earlierCost,2):'0';
 return bccomp($periodCost,$available,2)>0?bcsub($periodCost,$available,2):'0';
}
$due='0';$cohortPaid='0';foreach($expenseCohort as $e){$due=bcadd($due,bccomp($e['total'],$e['paid'],2)>0?bcsub($e['total'],$e['paid'],2):'0',2);$cohortPaid=bcadd($cohortPaid,$e['paid'],2);}
$prepaid='0';foreach($contracts as $c){$prepaid=bcadd($prepaid,bccomp($c['paid'],$c['recognized'],2)>0?bcsub($c['paid'],$c['recognized'],2):'0',2);if(isset($contractPeriod[$c['id']]))$due=bcadd($due,report_contract_due($contractPeriod[$c['id']],$c['paid'],$contractBefore[$c['id']]??'0'),2);}
function report_detail_link(array $l):string{return '<a href="index.php?page=expenses&amp;view='.(int)$l['expense_id'].'">#'.(int)$l['expense_id'].'</a>';}
?>
