</div>
<details class="rp-more-filters" <?=$activeFilterCount?'open':''?>><summary>More filters<?php if($activeFilterCount):?><span class="rp-filter-count"><?=$activeFilterCount?> active</span><?php endif ?></summary>
<div class="rp-filter-grid">
<?php $selects=['contact'=>['Contact','contacts',$contactId]];if($lineFilters||$tab==='labour')$selects['work']=['Work type','work_types',$workId];if($lineFilters){$selects['category']=['Category','categories',$categoryId];$selects['item']=['Item','items',$itemId];}foreach($selects as $key=>[$label,$table,$selected]):?><div class="rp-field"><label for="<?=e($key)?>"><?=e($label)?></label><select class="form-select" id="<?=e($key)?>" name="<?=e($key)?>"><option value="">All <?=e(['contact'=>'contacts','work'=>'work types','category'=>'categories','item'=>'items'][$key])?></option><?php foreach(rows("SELECT id,name FROM $table ORDER BY name") as $r):?><option value="<?=(int)$r['id']?>" <?=$selected===$r['id']||$selected===(int)$r['id']?'selected':''?>><?=e($r['name'])?></option><?php endforeach ?></select></div><?php endforeach ?>
<?php if($lineFilters):?><div class="rp-field"><label for="payment_status">Purchase payment</label><select class="form-select" name="payment_status" id="payment_status"><option value="">All payment statuses</option><?php foreach(['paid','partial','unpaid'] as $s):?><option <?=$paymentStatus===$s?'selected':''?> value="<?=$s?>"><?=ucfirst($s)?></option><?php endforeach ?></select></div><?php endif ?>
</div></details></form>
