<header class="rp-result-heading"><div><h2 id="report-title"><?=e($tabs[$tab])?></h2><p><?=e($reportDescriptions[$tab])?></p></div><span class="rp-period"><?=e($periodLabels[$preset])?><?php if($from!==''||$to!==''):?><small><?=e(($from?:'Any date').' – '.($to?:'Any date'))?></small><?php endif ?></span></header>
<?php if(in_array($tab,['overall','suppliers'],true)):?><p class="rp-scope">Costs follow purchase and approved-work dates. Payments follow payment dates. Outstanding covers matching whole purchases and period work, using allocations from all payment dates.<?php if($tab==='overall'):?> Cash paid is filtered by date and contact only.<?php endif ?></p><?php endif ?>
<?php if($tab==='overall'): ?>
<div class="rp-metrics"><?php $material='0';$labour=$workTotal;foreach($lines as $l){if($l['kind']==='material')$material=bcadd($material,$l['total'],2);if($l['kind']==='labour')$labour=bcadd($labour,$l['total'],2);}foreach(['Recorded expenses'=>bcadd($purchaseTotal,$workTotal,2),'Cash paid in period'=>report_sum($payments,'amount'),'Outstanding on matching records'=>$due,'Unallocated payments in period'=>$unallocated,'Material cost'=>$material,'Labour / Theka cost'=>$labour] as $label=>$amount):?><div class="rp-metric"><span><?=e($label)?></span><strong><?=money($amount)?></strong></div><?php endforeach ?></div>
<details class="rp-notes"><summary>How these figures are calculated</summary><p>Expenses use purchase/work dates. Cash paid uses payment dates and supplier only; item, category, work and purchase payment filters do not filter cash. Outstanding includes matching whole purchases, even when item/category/work filters select only some lines. Matching whole purchase total: <?=money(report_sum($expenseCohort,'total'))?>. Allocations on matching whole purchases (all payment dates): <?=money($cohortPaid)?>. Contract payments offset earlier recognized work first, then selected-period work; allocations from all payment dates apply. These are current unpaid cohort amounts, not historical closing balances. Contract prepayments (all dates, selected contractor/work): <?=money($prepaid)?>. Commitments excluded.</p></details>
<?php elseif($tab==='materials'): $groups=[];
foreach($lines as $l){$target=null;$factor='1';if(!$l['is_fixed'])foreach($groups as $k=>$g){if($g['item_id']!=$l['item_id']||$g['fixed'])continue;try{$factor=conversion((int)$l['unit_id'],(int)$g['unit_id']);$target=$k;break;}catch(Throwable $exception){}}
if($target===null){$target=$l['item_id'].':'.($l['is_fixed']?'fixed':$l['unit_id']);if(!isset($groups[$target]))$groups[$target]=['item_id'=>$l['item_id'],'name'=>$l['item_name'],'unit_id'=>$l['unit_id'],'unit'=>$l['unit_name'],'fixed'=>$l['is_fixed'],'quantity'=>'0','amount'=>'0','purchases'=>[]];$factor='1';}
$g=&$groups[$target];$g['amount']=bcadd($g['amount'],$l['total'],2);if(!$l['is_fixed'])$g['quantity']=bcadd($g['quantity'],bcmul($l['quantity'],$factor,8),8);$g['purchases'][$l['expense_id']]=true;unset($g);}
?>
<details class="rp-notes"><summary>About quantities and average rates</summary><p>Compatible units combine only through configured conversions. Average rate = total cost ÷ converted quantity, per displayed unit. Fixed charges are separate.</p></details>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Material / item</th><th class="rp-number">Quantity</th><th>Unit</th><th class="rp-number">Amount</th><th class="rp-number">Weighted rate / unit</th><th class="rp-number">Purchases</th></tr></thead><tbody><?php foreach($groups as $g):?><tr><td><a href="index.php?<?=e(http_build_query(array_merge($_GET,['page'=>'reports','tab'=>'rates','item'=>$g['item_id']])))?>"><?=e($g['name'])?></a><?= $g['fixed']?' (fixed charge)':''?></td><td class="rp-number"><?=$g['fixed']?'—':e(rtrim(rtrim($g['quantity'],'0'),'.'))?></td><td><?=$g['fixed']?'—':e($g['unit'])?></td><td class="rp-number"><?=money($g['amount'])?></td><td class="rp-number"><?=!$g['fixed']&&bccomp($g['quantity'],'0',8)>0?money(bcdiv($g['amount'],$g['quantity'],2)):'—'?></td><td class="rp-number"><?=count($g['purchases'])?></td></tr><?php endforeach ?></tbody></table></div>
<?php elseif($tab==='rates'): ?>
<details class="rp-notes"><summary>How to compare rates</summary><p>Original quantity, units, rates and pricing basis preserved. Compare original rates only when units and basis match; Materials tab provides normalized weighted averages.</p></details>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Date / purchase</th><th>Item</th><th class="rp-number">Quantity</th><th class="rp-number">Original rate / basis</th><th>Supplier</th><th>Work type</th><th class="rp-number">Amount</th></tr></thead><tbody><?php foreach($lines as $l):?><tr><td><?=e($l['expense_date'])?> <?=report_detail_link($l)?></td><td><?=e($l['description'])?></td><td class="rp-number"><?=$l['is_fixed']?'—':e($l['quantity'].' '.$l['unit_name'])?></td><td class="rp-number"><?=money($l['rate'])?><?=$l['is_fixed']?' fixed':' / '.e($l['rate_basis'].' '.$l['rate_unit_name'])?></td><td><?=e($l['contact_name']??'—')?></td><td><?=e($l['work_name'])?></td><td class="rp-number"><?=money($l['total'])?></td></tr><?php endforeach ?></tbody></table></div>
<?php elseif(in_array($tab,['categories','work','dates'],true)): $groups=[];
foreach($lines as $l){$key=$tab==='categories'?$l['category_id']:($tab==='work'?$l['work_type_id']:$l['expense_date']);$name=$tab==='categories'?$l['category_name']:($tab==='work'?$l['work_name']:$l['expense_date']);report_group($groups,(string)$key,$name,$l['total']);$groups[$key]['links']['e'.$l['expense_id']]=report_detail_link($l);}
foreach($costs as $w){$key=$tab==='categories'?'contract':($tab==='work'?$w['work_type_id']:$w['cost_date']);$name=$tab==='categories'?'Labour / Theka (recognized work)':($tab==='work'?$w['work_name']:$w['cost_date']);report_group($groups,(string)$key,$name,$w['amount']);$groups[$key]['links']['c'.$w['contract_id']]='<a href="index.php?page=contracts&amp;view='.(int)$w['contract_id'].'">'.e($w['title']).'</a>';}
if($tab==='dates')krsort($groups);
?>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th><?=e($tabs[$tab])?></th><th class="rp-number">Expense</th><th>Underlying details</th></tr></thead><tbody><?php foreach($groups as $g):?><tr><td><?=e($g['name'])?></td><td class="rp-number"><?=money($g['amount'])?></td><td><?=implode(', ',$g['links'])?></td></tr><?php endforeach ?></tbody><tfoot><tr><th>Total</th><th class="rp-number"><?=money(bcadd($purchaseTotal,$workTotal,2))?></th><td></td></tr></tfoot></table></div>
<?php elseif($tab==='labour'): ?>
<p class="rp-scope">Commitment and balances cover all dates. Activity columns follow the selected period.</p><details class="rp-notes"><summary>About contract figures</summary><p>Commitment, recognized work, payments and balances are lifetime contract figures. Selected dates filter recognized-work and payment activity columns; contracts with no activity in that period are hidden.</p></details>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Contract / contractor</th><th>Work / status</th><th class="rp-number">Agreed</th><th class="rp-number">Recognized (all dates)</th><th class="rp-number">Paid (all dates)</th><th class="rp-number">Remaining commitment</th><th class="rp-number">Payment balance</th><th class="rp-number">Work in period</th><th class="rp-number">Paid in period</th></tr></thead><tbody><?php $shownContracts=0;foreach($contracts as $c):$periodPaid='0';foreach($paymentLinks as $a)if($a['contract_id']==$c['id']&&($from===''||$a['payment_date']>=$from)&&($to===''||$a['payment_date']<=$to))$periodPaid=bcadd($periodPaid,$a['amount'],2);if(($from!==''||$to!=='')&&!isset($contractPeriod[$c['id']])&&bccomp($periodPaid,'0',2)===0)continue;$shownContracts++;?><tr><td><a href="index.php?page=contracts&view=<?=(int)$c['id']?>"><?=e($c['title'])?></a><br><?=e($c['contact_name'])?></td><td><?=e($c['work_name'].' / '.$c['status'])?></td><td class="rp-number"><?=money($c['agreed_amount'])?></td><td class="rp-number"><?=money($c['recognized'])?></td><td class="rp-number"><?=money($c['paid'])?></td><td class="rp-number"><?=money(bcsub($c['agreed_amount'],$c['recognized'],2))?></td><td class="rp-number"><?=money(bcsub($c['agreed_amount'],$c['paid'],2))?></td><td class="rp-number"><?=money($contractPeriod[$c['id']]??'0')?></td><td class="rp-number"><?=money($periodPaid)?></td></tr><?php endforeach ?></tbody></table></div>
<?php elseif($tab==='suppliers'): $suppliers=[];
foreach(rows('SELECT id,name FROM contacts ORDER BY name') as $n)if(!$contactId||$contactId===$n['id']||$contactId===(int)$n['id'])$suppliers[$n['id']]=['name'=>$n['name'],'purchase'=>'0','work'=>'0','paid'=>'0','due'=>'0','advance'=>'0'];
foreach($expenseCohort as $id=>$e){$contact=null;foreach($lines as $l)if($l['expense_id']==$id){$contact=$l['contact_id'];break;}if(!isset($suppliers[$contact]))continue;$s=&$suppliers[$contact];$s['purchase']=bcadd($s['purchase'],$e['total'],2);$s['due']=bcadd($s['due'],bccomp($e['total'],$e['paid'],2)>0?bcsub($e['total'],$e['paid'],2):'0',2);unset($s);}
foreach($costs as $w)if(isset($suppliers[$w['contact_id']]))$suppliers[$w['contact_id']]['work']=bcadd($suppliers[$w['contact_id']]['work'],$w['amount'],2);
foreach($contracts as $c)if(isset($contractPeriod[$c['id']])&&isset($suppliers[$c['contact_id']]))$suppliers[$c['contact_id']]['due']=bcadd($suppliers[$c['contact_id']]['due'],report_contract_due($contractPeriod[$c['id']],$c['paid'],$contractBefore[$c['id']]??'0'),2);
foreach($payments as $p)if(isset($suppliers[$p['contact_id']])){$s=&$suppliers[$p['contact_id']];$s['paid']=bcadd($s['paid'],$p['amount'],2);$s['advance']=bcadd($s['advance'],bcsub($p['amount'],$p['allocated'],2),2);unset($s);}
?>
<details class="rp-notes"><summary>How contact balances are calculated</summary><p>Purchases and work use expense dates; paid and unallocated advances use payment dates. Outstanding covers matching whole purchases and selected-period contract work. Contract payments offset earlier recognized work first, then period work. Allocations from all payment dates apply; this is not a historical closing balance. Anonymous purchases/payments have no supplier ledger.</p></details>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Supplier / contractor</th><th class="rp-number">Purchases</th><th class="rp-number">Recognized work</th><th class="rp-number">Paid in period</th><th class="rp-number">Outstanding</th><th class="rp-number">Unallocated in period</th></tr></thead><tbody><?php foreach($suppliers as $id=>$s):?><tr><td><a href="index.php?<?=e(http_build_query(array_merge($_GET,['page'=>'reports','contact'=>$id])))?>"><?=e($s['name'])?></a></td><td class="rp-number"><?=money($s['purchase'])?></td><td class="rp-number"><?=money($s['work'])?></td><td class="rp-number"><?=money($s['paid'])?></td><td class="rp-number"><?=money($s['due'])?></td><td class="rp-number"><?=money($s['advance'])?></td></tr><?php endforeach ?></tbody></table></div>
<?php if($contactId):?><h3 class="h5">Supplier ledger — period activity</h3><div class="table-responsive" tabindex="0" role="region" aria-label="Contact ledger, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Date</th><th>Record</th><th class="rp-number">Expense</th><th class="rp-number">Paid</th></tr></thead><tbody><?php $ledger=[];foreach($expenseCohort as $id=>$e)foreach($lines as $l)if($l['expense_id']==$id){$ledger[]=['date'=>$l['expense_date'],'link'=>report_detail_link($l),'expense'=>$e['total'],'paid'=>'0'];break;}foreach($costs as $w)$ledger[]=['date'=>$w['cost_date'],'link'=>'<a href="index.php?page=contracts&amp;view='.(int)$w['contract_id'].'">'.e($w['title']).'</a>','expense'=>$w['amount'],'paid'=>'0'];foreach($payments as $p)$ledger[]=['date'=>$p['payment_date'],'link'=>'<a href="index.php?page=payments&amp;view='.(int)$p['id'].'">Payment #'.(int)$p['id'].'</a>','expense'=>'0','paid'=>$p['amount']];usort($ledger,fn($a,$b)=>strcmp($a['date'],$b['date']));foreach($ledger as $r):?><tr><td><?=e($r['date'])?></td><td><?=$r['link']?></td><td class="rp-number"><?=money($r['expense'])?></td><td class="rp-number"><?=money($r['paid'])?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php elseif($tab==='payments'): ?>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?=e($tabs[$tab])?> report table, scroll horizontally to view all columns"><table class="table rp-table"><thead><tr><th>Date</th><th>Recipient</th><th>Method</th><th class="rp-number">Amount</th><th>Allocations</th><th class="rp-number">Unallocated</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><a href="index.php?page=payments&view=<?=(int)$p['id']?>"><?=e($p['payment_date'])?></a></td><td><?=e($p['contact_name']??'—')?></td><td><?=e($p['method'])?></td><td class="rp-number"><?=money($p['amount'])?></td><td><?php foreach($linksByPayment[$p['id']]??[] as $a):?><div><a href="index.php?page=<?=$a['expense_id']?'expenses':'contracts'?>&view=<?=(int)($a['expense_id']?:$a['contract_id'])?>"><?=e($a['expense_id']?'Purchase #'.$a['expense_id']:$a['title'])?></a>: <?=money($a['amount'])?></div><?php endforeach ?></td><td class="rp-number"><?=money(bcsub($p['amount'],$p['allocated'],2))?></td></tr><?php endforeach ?></tbody><tfoot><tr><th colspan="3">Total</th><th class="rp-number"><?=money(report_sum($payments,'amount'))?></th><td></td><th class="rp-number"><?=money($unallocated)?></th></tr></tfoot></table></div>
<?php endif ?>

<?php $noData = match($tab) { 'payments'=>!$payments, 'suppliers'=>!$suppliers, 'labour'=>!$shownContracts, 'materials','rates'=>!$lines, 'overall'=>!$lines&&!$costs&&!$payments, default=>!$lines&&!$costs }; if($noData): ?><div class="rp-empty" role="status"><strong>No matching records</strong><p>Try a wider date range or reset the filters.</p><a class="rp-reset" href="index.php?page=reports&amp;tab=<?=e($tab)?>">Reset filters</a></div><?php endif ?>

</section>
